ControlPropertyState.AutoRuleBindingString:
// =========================================
// galPunches.OnSelect  (NORMALIZED + CLEAN)
// =========================================

// 0) Abrir drawer y estado base UI
Set(varShowDetailDrawer, true);
Set(varDrawerIsLoading, true);

// Tabs / paginación (una sola vez)
Set(varDrawerTab, "Overview");
Set(tablistSelected, 1);

Set(varCommentsPageSize, 20);
Set(varCommentsPage, 1);

// 1) Contexto del drawer (identidad del registro)
Set(varDrawerProjectId, varProjectId);
Set(varDrawerEntityType, "PUNCH");
Set(varDrawerRecordId, ThisItem.PunchId);

// Guardar record crudo (por si hay cosas específicas en otras tabs)
Set(varDrawerSelectedRecord, ThisItem);

// 2) NORMALIZACIÓN (record común para Overview)
Set(
    varDrawerNormalized,
    {
        EntityType: "PUNCH",
        ProjectId: varProjectId,
        RecordId: ThisItem.PunchId,

        // WBS
        AreaCode: Coalesce(Text(ThisItem.AreaCode), ""),
        UnitCode: Coalesce(Text(ThisItem.UnitCode), ""),
        SystemCode: Coalesce(Text(ThisItem.SystemCode), ""),
        SubsystemCode: Coalesce(Text(ThisItem.SubsystemCode), ""),
        ElementCode: Coalesce(Text(ThisItem.ElementCode), ""),
        TypeCode: Coalesce(Text(ThisItem.TypeCode), ""),

        // Slots + etiquetas
        TitleLabel: "Punch Code:",
        TitleValue: Coalesce(Text(ThisItem.PunchCode), Text(ThisItem.PunchId), "-"),

        DescLabel: "Punch Description:",
        DescValue: Coalesce(Text(ThisItem.PunchDescription), Text(ThisItem.PunchDescription), "-"),

        StatusLabel: "Punch Status:",
        StatusValue: Coalesce(Text(ThisItem.PunchStatus), Text(ThisItem.PunchStatus), "-"),

        DisciplineLabel: "Punch Discipline:",
        DisciplineValue: Coalesce(Text(ThisItem.PunchDiscipline), Text(ThisItem.PunchDiscipline), "-"),

        SecondaryLabel: "Inspection:",
        SecondaryValue: Coalesce(Text(ThisItem.InspectionName), "")
    }
);

// 3) Limpieza de estados dependientes (Custom/Comments/etc.)
Set(varCT_LoadKey, ""); // fuerza reload de Custom al entrar
Clear(colCT_Merged);
Clear(colCT_Quick);
Clear(colCT_Dirty);

// 4) Reset del componente (solo si tu diseño lo necesita)
Reset(comp_DetailDrawer);

// 5) Disparar carga del drawer (tu loader central)
Select(btnDrawerLoad);

Switch(
    Coalesce(varTasks_ReturnView, "Overview"),

    "Home",
        Set(varAppView, "Home");
        Set(varHomeViewMode, "DASHBOARD"),

    "Overview",
        Set(varAppView, "Overview");
        Set(varOps_ViewMode, "OVERVIEW"),

    Set(varAppView, "Overview");
    Set(varOps_ViewMode, "OVERVIEW")
)

Set(varCT_DefsIsLoading, true);
Set(varCT_DefsError, "");

Clear(colCT_Defs_Admin);

Set(
    varCT_DefsResp,
    WarRoom_ListCustomFieldDefs.Run(
        comp_DetailDrawer_2.ProjectId,
        comp_DetailDrawer_2.EntityType,
        If(varCT_ShowInactiveDefs, 1, 0)
    )
);


Set(
    varCT_DefsOuter,
    Table(ParseJSON(Coalesce(varCT_DefsResp.result, "[]")))
);

If(
    CountRows(varCT_DefsOuter) = 0,

    Set(varCT_DefsError, "The flow returned no data."),

    Set(
        varCT_DefsBundle,
        ParseJSON(
            Text(First(varCT_DefsOuter).Value.result)
        )
    );

    ClearCollect(
        colCT_Defs_Admin,
        ForAll(
            Table(varCT_DefsBundle.defs),
            {
                FieldDefId: Value(ThisRecord.Value.FieldDefId),
                ProjectId: Value(ThisRecord.Value.ProjectId),
                EntityType: Text(ThisRecord.Value.EntityType),
                FieldKey: Text(ThisRecord.Value.FieldKey),
                Label: Text(ThisRecord.Value.Label),
                FieldType: Text(ThisRecord.Value.FieldType),
                HelpText: Coalesce(Text(ThisRecord.Value.HelpText), ""),
                IsRequired: Boolean(ThisRecord.Value.IsRequired),
                IsPinned: Boolean(ThisRecord.Value.IsPinned),
                IsActive: Boolean(ThisRecord.Value.IsActive),
                SortOrder: Value(ThisRecord.Value.SortOrder),
                OptionsJson: Coalesce(Text(ThisRecord.Value.OptionsJson), ""),
                ModifiedOn: If(
                    IsBlank(Text(ThisRecord.Value.ModifiedOn)),
                    Blank(),
                    DateTimeValue(Text(ThisRecord.Value.ModifiedOn))
                ),
                ModifiedByEmail: Coalesce(Text(ThisRecord.Value.ModifiedByEmail), "")
            }
        )
    )
);

Set(varCT_DefsIsLoading, false);

Set(varIsLoadingComments, true);

Set(varCommentsPage, 1);
Set(varCommentsPageSize, Coalesce(varCommentsPageSize, 20));

With(
    {
        resp: Warroom_GetTaskCommentsPaged.Run(
            varProjectId,
            varDrawerRecordId,
            varCommentsPage,
            varCommentsPageSize,
            varDrawerEntityType
        )
    },
    With(
        {
            arr: Table(ParseJSON(Coalesce(resp.result, "[]")))
        },
        ClearCollect(
            colComments,
            ForAll(
                arr,
                {
                    CommentId: Value(ThisRecord.Value.CommentId),
                    CommentText: Text(ThisRecord.Value.CommentText),
                    CommentType: Text(ThisRecord.Value.CommentType),
                    CreatedOn: DateTimeValue(Text(ThisRecord.Value.CreatedOn)),
                    CreatedByEmail: Text(ThisRecord.Value.CreatedByEmail),
                    CreatedByName: Text(ThisRecord.Value.CreatedByName),
                    TotalRows: Value(ThisRecord.Value.TotalRows),
                    TotalPages: Value(ThisRecord.Value.TotalPages),
                    PageNumber: Value(ThisRecord.Value.PageNumber),
                    PageSize: Value(ThisRecord.Value.PageSize)
                }
            )
        )
    )
);

Set(varCommentsTotalRows, If(CountRows(colComments) > 0, First(colComments).TotalRows, 0));
Set(varCommentsTotalPages, If(CountRows(colComments) > 0, First(colComments).TotalPages, 0));

Set(varIsLoadingComments, false);
Set(varDrawerIsLoading, false);

Set(varCT_Loading, true);
Set(varCT_Error, "");

// Limpieza
Clear(colCT_Quick);
Clear(colCT_Merged_Base);
Clear(colCT_Merged_UI);

// Llamada al flow
With(
    {
        resp: WarRoom_GetCustomBundle.Run(
            comp_DetailDrawer_2.ProjectId,
            comp_DetailDrawer_2.EntityType,
            comp_DetailDrawer_2.RecordId
        )
    },

    With(
        {
            parsed: ParseJSON(Coalesce(resp.bundlejson, "{}"))
        },

        // Base (defs)
        ClearCollect(
            colCT_Merged_Base,
            ForAll(
                Table(parsed.defs),
                {
                    FieldKey: Text(ThisRecord.Value.FieldKey),
                    Label: Text(ThisRecord.Value.Label),
                    FieldType: Text(ThisRecord.Value.FieldType),
                    IsRequired: Boolean(ThisRecord.Value.IsRequired),
                    IsPinned: Boolean(ThisRecord.Value.IsPinned),
                    SortOrder: Value(ThisRecord.Value.SortOrder),
                    OptionsJson: Text(ThisRecord.Value.OptionsJson)
                }
            )
        );

        // Valores (values)
        ClearCollect(
            colCT_Merged_UI,
            ForAll(
                Table(parsed.values),
                {
                    FieldKey: Text(ThisRecord.Value.FieldKey),
                    ValueText: Text(ThisRecord.Value.ValueText),
                    ValueNumber: Value(ThisRecord.Value.ValueNumber),
                    ValueDate: If(
                        !IsBlank(ThisRecord.Value.ValueDate),
                        DateTimeValue(Text(ThisRecord.Value.ValueDate)),
                        Blank()
                    ),
                    ValueBool: Boolean(ThisRecord.Value.ValueBool)
                }
            )
        )
    )
);

// Merge final (lo que pinta la UI)
ClearCollect(
    colCT_Quick,
    AddColumns(
        colCT_Merged_Base,
        CurrentValue,
        LookUp(colCT_Merged_UI, FieldKey = ThisRecord.FieldKey)
    )
);

Set(varCT_Loading, false);

Set(varDrawerIsLoading, true);

Switch(
    varDrawerTab,
    "Comments", Select(btnDrawerLoad_Comments_2),
    "Custom", Select(btnDrawerLoad_Custom_2),
    "Overview", Set(varDrawerIsLoading, false),
    "History", Set(varDrawerIsLoading, false),
    Set(varDrawerIsLoading, false)
);

Set(varPunchExportMode, "CLIENT");

UpdateIf(
    colPunchExportColumns,
    IsSensitive && !IsRequired,
    { IsSelected: false }
);

UpdateIf(
    colPunchExportColumns,
    !IsSensitive || IsRequired,
    { IsSelected: true }
)

If(
    CountRows(
        Filter(
            colPunchExportColumns,
            IsSelected
        )
    ) = 0,

    Notify(
        "Select at least one export column.",
        NotificationType.Warning
    ),

    Set(
        varPunchExportColumnsJson,
        JSON(
            ShowColumns(
                SortByColumns(
                    Filter(
                        colPunchExportColumns,
                        IsSelected
                    ),
                    "SortOrder",
                    SortOrder.Ascending
                ),
                ColumnKey,
                ColumnLabel,
                SortOrder
            ),
            JSONFormat.Compact
        )
    );

    Set(varShowPunchExportColumns, false);

    Notify(
        Text(
            CountRows(
                Filter(
                    colPunchExportColumns,
                    IsSelected
                )
            )
        ) &
        " columns prepared for export.",
        NotificationType.Success
    )
)

Set(varPunchExportMode, "INTERNAL");

UpdateIf(
    colPunchExportColumns,
    true,
    { IsSelected: true }
)

UpdateIf(
    colPunchExportColumns,
    !IsSensitive || IsRequired,
    { IsSelected: true }
);

UpdateIf(
    colPunchExportColumns,
    IsSensitive && !IsRequired,
    { IsSelected: false }
)

With(
    {
        _key: Lower(Trim(Self.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId),
        _hasConfig: varProjectHasReportConfig || varHomeHiveLoaded || varProjectHasPHRData
    },

    If(
        _key = "superadmin",

        Set(varGlobalLoading, false);
        Set(varGlobalLoadingMsg, "");
        Set(varGlobalLoadingSubMsg, "");
        Set(varGlobalLoadingScope, "");
        Set(varGlobalLoadAction, "");
        Set(varGlobalLoadPending, false);

        Set(varPHR_IsLoading, false);
        Set(varOps_IsLoading, false);
        Set(varTasks_IsLoading, false);
        Set(varPunches_IsLoading, false);
        Set(varCfg_IsLoading, false);

        Set(varAppView, "SuperAdmin");
        Set(varPageKey, "SUPERADMIN");
        Set(varPageTitle, "Administration");
        Set(varPageSubtitle, "Platform configuration and governance");

        Navigate(scr_SuperAdmin, ScreenTransition.None),

        If(
            _key <> "home" && !_hasProject,

            Notify("Please select a project first.", NotificationType.Warning);

            Set(varAppView, "Home");
            Set(varPageKey, "HOME");
            Set(varPageTitle, "Home");
            Set(varPageSubtitle, "Project command center");

            Navigate(scr_Home, ScreenTransition.None),

            If(
                _key in ["overview", "tasks", "punches", "briefing", "config", "skyline"] && !_hasConfig,

                Notify(
                    "This project has no published report configuration yet.",
                    NotificationType.Warning
                );

                Set(varAppView, "Home");
                Set(varPageKey, "HOME");
                Set(varPageTitle, "Home");
                Set(varPageSubtitle, "Project command center");

                Navigate(scr_Home, ScreenTransition.None),

                Switch(
                    _key,

                    "skyline",
                    Set(varAppView, "Skyline");
                    Set(varPageKey, "SKYLINE");
                    Set(varPageTitle, "Delivery Skyline");
                    Set(varPageSubtitle, "Weekly subsystem delivery risk and workload forecast");
                    Set(varSkylineLoaded, false);
                    Set(varSkylineError, "");
                    Clear(colSkylineRaw);
                    Clear(colSkylineWeeks);
                    Clear(colSkylineSelectedWeek);

                    Navigate(scr_Skyline, ScreenTransition.None),


                    "home",
                        Set(varGlobalLoading, false);
                        Set(varGlobalLoadingMsg, "");
                        Set(varGlobalLoadingSubMsg, "");
                        Set(varGlobalLoadingScope, "");
                        Set(varGlobalLoadAction, "");
                        Set(varGlobalLoadPending, false);

                        Set(varPHR_IsLoading, false);
                        Set(varOps_IsLoading, false);
                        Set(varTasks_IsLoading, false);
                        Set(varPunches_IsLoading, false);
                        Set(varCfg_IsLoading, false);

                        Set(varAppView, "Home");
                        Set(varPageKey, "HOME");
                        Set(varPageTitle, "Home");
                        Set(varPageSubtitle, "Project command center");
                        Set(varHomeViewMode, "DASHBOARD");

                        Navigate(scr_Home, ScreenTransition.None),

                    "overview",
                        Set(varAppView, "Overview");
                        Set(varPageKey, "OVERVIEW");
                        Set(varPageTitle, "Overview");
                        Set(varPageSubtitle, "Project Handover Report by subsystem, discipline and form family");
                        Set(varOps_ViewMode, "OVERVIEW");

                        Navigate(scr_Overview, ScreenTransition.None),



                    "tasks",
                        Set(varAppView, "Tasks");
                        Set(varPageKey, "TASKS");
                        Set(varPageTitle, "Tasks");
                        Set(varPageSubtitle, "Inspection task management");

                        Navigate(scr_Tasks, ScreenTransition.None),

                    "punches",
                        Set(varAppView, "Punches");
                        Set(varPageKey, "PUNCHES");
                        Set(varPageTitle, "Punch List");
                        Set(varPageSubtitle, "Punch item management");

                        Navigate(scr_Punches, ScreenTransition.None),

                    "briefing",
                        Set(varAppView, "Briefing");
                        Set(varPageKey, "BRIEFING");
                        Set(varPageTitle, "Briefing");
                        Set(varPageSubtitle, "Project reporting and communication");

                        Navigate(scr_Briefing, ScreenTransition.None),

                    "config",
                        Set(varAppView, "Config");
                        Set(varPageKey, "CONFIG");
                        Set(varPageTitle, "Configuration");
                        Set(varPageSubtitle, "Report structure and scope management");

                        Navigate(scr_Config, ScreenTransition.None),

                    Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
                )
            )
        )
    )
)
